customCSS:
.t, .history { color: #99968b; }
.join { color: #95e454; }
.part, .quit { color: #99968b; }
.kick, .error { color: #e5786d; }
.notice { color: #cae682; }
.action { color: #f2c68a; }
.mode, .nick, .topic, .server { color: #8ac6f2; }
.highlight { color: #f6f3e8; background-color: #554d4b; border-left: 3px solid #f2c68a; padding-left: 8px; }
.reply { color: #99968b; border-left: 2px solid #8ac6f2; padding-left: 6px; }
.oper { color: #242424; background-color: #cae682; }
.reactions { color: #8ac6f2; background-color: #444444; }
.card { background-color: #444444; border-color: #99968b; }
.card-title { color: #8ac6f2; }
.card-desc { color: #99968b; }
.daychange { color: #99968b; border-color: #444444; }
